const data = $input.first().json.data;
const now = new Date();
const date = now.toLocaleDateString('pt-BR', { weekday: 'long', day: '2-digit', month: 'long' });

let msg = `📋 *Briefing — ${date}*\n\n`;

if (data.leadsToFollow.length > 0) {
  msg += `🔔 *Leads para contatar hoje:*\n`;
  data.leadsToFollow.forEach(l => {
    msg += `• ${l.name} (${l.company || '—'}) — ${l.stage}\n`;
  });
  msg += '\n';
}

if (data.overdueInvoices.length > 0) {
  msg += `💸 *Faturas atrasadas:*\n`;
  data.overdueInvoices.forEach(i => {
    msg += `• ${i.number} — ${i.name} — R$ ${parseFloat(i.amount).toLocaleString('pt-BR')}\n`;
  });
  msg += '\n';
}

if (data.overdueMilestones.length > 0) {
  msg += `⚠️ *Milestones atrasados:*\n`;
  data.overdueMilestones.forEach(m => {
    msg += `• ${m.title} (${m.project_name})\n`;
  });
  msg += '\n';
}

if (data.leadsToFollow.length === 0 && data.overdueInvoices.length === 0 && data.overdueMilestones.length === 0) {
  msg += '✅ Tudo em dia! Bom dia!\n';
}

msg += `\n_Enviado por ThiagoMKT Sistema_`;

return [{ json: { message: msg } }];
